#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [0.34490098, -0.234243005, -0.017180645], 'basis': [[0.0, -0.0, 1.0], [0.0, 1.0, 0.0], [-1.0, 0.0, 0.0]], 'axis': [1.0, 0.0, 0.0], 'zmin': -0.06703962000000002, 'zmax': 0.06703961999999997, 'profiles': [{'outer': [[-0.09413059500000001, -2.497499999998265e-05], [-0.09062852499999999, 0.006929125000000008], [-0.08007228499999999, 0.018335815000000005], [-0.072818015, 0.022988585000000006], [-0.065213505, 0.025389995], [-0.05695960684643466, 0.02705645905185667], [-0.050204645, 0.029092165000000003], [-0.044251135, 0.034095135], [-0.040448905, 0.04325053500000001], [-0.038447705, 0.054857464999999994], [-0.037697265, 0.06666439500000002], [-0.037297045, 0.084775035], [-0.036946835, 0.090078145], [-0.036346485, 0.09338006500000001], [-0.035345885, 0.095331165], [-0.033895035000000004, 0.096281795], [-0.028491835, 0.099183525], [-0.026840865000000002, 0.099383625], [-0.015434125000000002, 0.10043433500000001], [0.0013758049999999973, 0.099333645], [0.020837295, 0.096481975], [0.039598385, 0.092479585], [0.054457145000000005, 0.087876855], [0.055707895, 0.087276515], [0.064262965, 0.08252373500000001], [0.065163485, 0.081222985], [0.066614335, 0.07697042500000001], [0.066814445, 0.074869185], [0.06606400500000001, 0.07151722500000002], [0.06416287500000001, 0.066464215], [0.056608435000000006, 0.04930409499999999], [0.052055744999999994, 0.037747295000000014], [0.048853854999999995, 0.025690135000000003], [0.04851385730569988, 0.015198575080722832], [0.052205825000000004, 0.008179815000000007], [0.059410105, 0.0019260950000000165], [0.076670295, -0.009230495000000005], [0.08532541499999999, -0.01633462499999999], [0.092279515, -0.02463957499999997], [0.09603173500000001, -0.033644854999999974], [0.09623184500000001, -0.03544592499999999], [0.09583161500000001, -0.045301764999999994], [0.09032837499999999, -0.05555778499999997], [0.08122299499999999, -0.06516346499999998], [0.078821575, -0.066914525], [0.068765625, -0.07396870500000002], [0.05915995499999999, -0.07782092499999999], [0.051055184999999996, -0.07792100499999999], [0.044201115, -0.07481914499999998], [0.038497755, -0.06946602499999999], [0.033644895, -0.06326237499999998], [0.029492434999999997, -0.05765906500000001], [0.025740214999999997, -0.05335655499999997], [0.023051918498225434, -0.051387548797246996], [0.023538924999999995, -0.054207055000000004], [0.025139864999999997, -0.06066086500000001], [0.026490674999999998, -0.06786510499999998], [0.026840875, -0.07066676500000002], [0.027291144999999996, -0.078221235], [0.026040404999999996, -0.08547550500000001], [0.022488305, -0.09172925500000001], [0.015984464999999996, -0.09638193499999997], [0.013182804999999999, -0.09748265499999997], [0.003927334999999997, -0.09993401499999999], [-0.007329305000000001, -0.10043433499999999], [-0.018535925, -0.09868338500000001], [-0.027941485000000002, -0.094931125], [-0.034745515000000005, -0.08932784500000002], [-0.039148105, -0.08192339500000001], [-0.041599554999999996, -0.073218285], [-0.042450065, -0.06416297500000001], [-0.042400025, -0.05585804500000002], [-0.041999785, -0.04845368499999997], [-0.042049815000000004, -0.04214996500000001], [-0.043250525, -0.037697225], [-0.04504725226928863, -0.0368479156117861], [-0.048153425, -0.03924807499999999], [-0.052305885, -0.04189974499999999], [-0.057458935, -0.043800805], [-0.068715585, -0.04475137499999998], [-0.074218825, -0.04335054500000002], [-0.082423675, -0.038797884999999976], [-0.087226525, -0.03404507499999998], [-0.092329515, -0.02629050500000002], [-0.095431355, -0.01738521500000001], [-0.09623184500000001, -0.010431145000000003], [-0.09563148499999999, -0.006378775000000003]], 'holes': []}], 'simplify_tolerance': 4.0173734000000004e-05, 'sketch_entity_count': 93}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
